import math, random

def fold(vals):
    f = 0.0
    for v in vals: f += v
    return f

def repair(vals, target, iters=12):
    r = list(vals); n = len(r)
    for _ in range(iters):
        f = fold(r)
        if f == target: return r
        d = target - f
        # try each entry, prefer candidates that exact-fold; rank by small rel perturb
        best_exact = None
        best_reduce = None
        order = sorted(range(n), key=lambda k: -abs(r[k]))
        for k in order:
            c = r.copy(); c[k] = r[k] + d
            ff = fold(c)
            if ff == target:
                rel = abs(d) / (abs(r[k]) or 1.0)
                if best_exact is None or rel < best_exact[0]:
                    best_exact = (rel, c)
            else:
                e = abs(ff - target)
                if best_reduce is None or e < best_reduce[0]:
                    best_reduce = (e, c)
        if best_exact is not None:
            return best_exact[1]
        if best_reduce is not None and best_reduce[0] < abs(f - target):
            r = best_reduce[1]
        else:
            break
    # guaranteed fallback: make last two entries absorb prefix/tail
    pref = fold(r[:n-2])
    r[n-2] = -pref
    r[n-1] = target
    return r

random.seed(7)
def datasets():
    ds = {}
    ds['normal'] = []
    for _ in range(100000):
        n = random.randint(1, 12)
        scale = random.choice([1.0, 1e6, 1e16, 1e300])
        ds['normal'].append([random.uniform(-scale, scale) for _ in range(n)])
    ds['cancel'] = []
    for _ in range(100000):
        big = random.choice([1e8, 1e10, 1e16, 1e200])
        ds['cancel'].append([big, random.uniform(-10,10), -big + random.uniform(-10,10),
                             random.uniform(-1,1)])
    ds['zeros'] = [[0.0, 0.0, 5.0], [0.0]*5 + [3.0], [1e-300, -1e-300, 2.5]]
    return ds

fails = 0; fallback_count = 0; maxrel = 0.0; maxrel_cancel = 0.0; worst=None
for name, data in datasets().items():
    for vals in data:
        T = math.fsum(vals)
        r = repair(vals, T)
        if fold(r) != T:
            fails += 1; continue
        scale = max(1.0, max(abs(v) for v in vals))
        rel = max(abs(a-b) for a,b in zip(r, vals))/scale
        if name == 'cancel': maxrel_cancel = max(maxrel_cancel, rel)
        else: maxrel = max(maxrel, rel)
        if rel > maxrel or (name=='cancel' and rel>maxrel_cancel): pass
        if rel > 1e-6:
            if worst is None or rel > worst[0]: worst=(rel, vals, r)
print("fails:", fails)
print("max rel perturb normal:", maxrel)
print("max rel perturb cancel:", maxrel_cancel)
print("worst:", worst)
