def reference(payload):
    cur = payload.get("currency", "USD")
    positions = [(p["id"], {f: float(v) for f, v in p["sensitivities"].items()}) for p in payload["positions"]]
    out = []
    worst_i, worst_v = 0, None
    for si, sc in enumerate(payload["scenarios"]):
        shocks = {f: float(v) for f, v in sc["factor_shocks"].items()}
        posc = {pid: 0.0 for pid, _ in positions}
        facs = []
        seen = set()
        for _, s in positions:
            for f in s:
                if f not in seen: seen.add(f); facs.append(f)
        facc = {f: 0.0 for f in facs}
        for pid, s in positions:
            sub = 0.0
            for f, sens in s.items():
                el = -sens * shocks.get(f, 0.0)
                sub += el; facc[f] += el
            posc[pid] = sub
        total = sum(posc.values())
        out.append({"id": sc["id"], "loss": total, "posc": posc, "facc": facc})
        if worst_v is None or total > worst_v:
            worst_v, worst_i = total, si
    return cur, out, (payload["scenarios"][worst_i]["id"], worst_v)

