import json, math, random
from riskscope.service import Service

random.seed(42)
svc = Service()
factors = ["eq", "ir", "fx", "cmd"]
def reference(positions, scenarios):
    P = [(p["id"], {f: float(v) for f,v in p["sensitivities"].items()}) for p in positions]
    facs = []; seen = set()
    for _, s in P:
        for f in s:
            if f not in seen: seen.add(f); facs.append(f)
    out = []; wi = 0; wv = None
    for si, sc in enumerate(scenarios):
        sh = {f: float(v) for f,v in sc["factor_shocks"].items()}
        posc = {pid: 0.0 for pid,_ in P}; facc = {f: 0.0 for f in facs}
        for pid, s in P:
            sub = 0.0
            for f, se in s.items():
                el = -se*sh.get(f,0.0); sub += el; facc[f] += el
            posc[pid] = sub
        total = sum(posc.values())
        out.append((sc["id"], total, posc, facc))
        if wv is None or total > wv: wv, wi = total, si
    return out, (scenarios[wi]["id"], wv)

def close(a,b,sc): return math.isclose(a,b,rel_tol=1e-12,abs_tol=max(1e-12,1e-11*sc))
fails = 0
for trial in range(10000):
    np_ = random.randint(1,8); ns = random.randint(1,8)
    positions = [{"id": f"p{i}", "sensitivities": {f: random.choice([random.randint(-1000,1000), round(random.uniform(-100,100),4)]) for f in random.sample(factors, random.randint(1,4))}} for i in range(np_)]
    scenarios = [{"id": f"s{i}", "factor_shocks": {f: random.choice([random.randint(-5,5), round(random.uniform(-0.5,0.5),3)]) for f in random.sample(factors+["extra"], random.randint(1,4))}} for i in range(ns)]
    got = svc.stress_test(json.dumps({"positions": positions, "scenarios": scenarios}).encode())
    ref, worst = reference(positions, scenarios)
    assert got["worst_scenario"]["id"] == worst[0]
    for g,(sid,loss,posc,facc) in zip(got["results"], ref):
        pc, fc = g["position_loss_contributions"], g["factor_loss_contributions"]
        if sum(pc.values()) != g["loss"] or sum(fc.values()) != g["loss"]:
            print("IDENTITY FAIL", trial, sid, g["loss"], sum(pc.values()), sum(fc.values())); fails += 1
        if sum(pc[k] for k in sorted(pc)) != g["loss"] or sum(fc[k] for k in sorted(fc)) != g["loss"]:
            print("SORTED-KEY FAIL", trial, sid); fails += 1
        sc = abs(loss) or 1
        if not close(g["loss"], loss, sc): print("LOSS MISMATCH", trial); fails += 1
        for pid,v in posc.items():
            if not (pc[pid]==v or close(pc[pid],v,sc)): print("POSC MISMATCH", trial, pid); fails += 1
        for f,v in facc.items():
            if not (fc[f]==v or close(fc[f],v,sc)): print("FACC MISMATCH", trial, f, fc[f], v); fails += 1
            if v == 0.0 and fc[f] != 0.0: print("ZERO CORRUPTED", trial, f); fails += 1
    if fails > 5: break
print("done, fails:", fails)
