import json, math, random
from riskscope.service import Service

# replicate internal path to grab factor bins + target for failing cases
random.seed(42)
svc = Service()
factors = ["eq","ir","fx","cmd"]

def pair_search(vals, T, K):
    nz = [i for i,v in enumerate(vals) if v != 0.0]
    for a in range(len(nz)):
        for b in range(a+1, len(nz)):
            i, j = nz[a], nz[b]
            oi, oj = vals[i], vals[j]
            si, sj = math.ulp(abs(oi)), math.ulp(abs(oj))
            for da in range(-K, K+1):
                ci = oi + da*si if da else oi
                for db in range(-K, K+1):
                    t = vals[:]; t[i], t[j] = ci, (oj + db*sj if db else oj)
                    if sum(t) == T: return (i, da, j, db)
    return None

need = {}
for trial in range(30000):
    np_ = random.randint(1,8)
    positions = [{"id": f"p{i}", "sensitivities": {f: random.choice([random.randint(-1000,1000), round(random.uniform(-100,100),4)]) for f in random.sample(factors, random.randint(1,4))}} for i in range(np_)]
    scenarios = [{"id": f"s{i}", "factor_shocks": {f: random.choice([random.randint(-5,5), round(random.uniform(-0.5,0.5),3)]) for f in random.sample(factors+["extra"], random.randint(1,4))}} for i in range(random.randint(1,8))]
    got = svc.stress_test(json.dumps({"positions": positions, "scenarios": scenarios}).encode())
    for g in got["results"]:
        fc = g["factor_loss_contributions"]; loss = g["loss"]
        sk = sorted(fc)
        vals = [fc[k] for k in sk]
        if sum(vals) == loss: continue
        # find minimal K resolving
